{
  "sets": [
    {
      "title": "Set 1: National Affairs, Policy & Governance",
      "questions": [
        {
          "source_id": "2",
          "evidence": "The Minister’s wife and daughters campaign for alliance candidates across city divisions, highlighting development works and seeking votes for mayoral candidate Roop Kumar Yadav",
          "prompt": {
            "en": "In Nellore, family members of Minister Narayana campaigned for alliance candidates and sought votes for which mayoral candidate?",
            "hi": "नेल्लोर में, मंत्री नारायण के परिवार के सदस्यों ने गठबंधन के उम्मीदवारों के लिए प्रचार किया और किस मेयर उम्मीदवार के लिए वोट मांगे?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "Roop Kumar Yadav",
                "hi": "रूप कुमार यादव"
              }
            },
            {
              "id": "b",
              "text": {
                "en": "Rakesh Shetty",
                "hi": "राकेश शेट्टी"
              }
            },
            {
              "id": "c",
              "text": {
                "en": "Kashim Chowdhury",
                "hi": "काशिम चौधरी"
              }
            },
            {
              "id": "d",
              "text": {
                "en": "V Harish",
                "hi": "वी हरीश"
              }
            }
          ],
          "correct_option_id": "a",
          "explanation": {
            "en": "The Minister's family campaigned for mayoral candidate Roop Kumar Yadav in Nellore.",
            "hi": "मंत्री के परिवार ने नेल्लोर में मेयर पद के उम्मीदवार रूप कुमार यादव के लिए प्रचार किया।"
          }
        },
        {
          "source_id": "3",
          "evidence": "Swadeshi Jagaran Manch says India must develop its own satellite internet infrastructure for both commercial and strategic reasons",
          "prompt": {
            "en": "Which organization urged Prime Minister Narendra Modi to deny operating permissions for SpaceX's Starlink?",
            "hi": "किस संगठन ने प्रधानमंत्री नरेंद्र मोदी से स्पेसएक्स के स्टारलिंक के लिए परिचालन अनुमति देने से इनकार करने का आग्रह किया है?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "Confederation of Indian Industry",
                "hi": "भारतीय उद्योग परिसंघ"
              }
            },
            {
              "id": "b",
              "text": {
                "en": "Swadeshi Jagaran Manch",
                "hi": "स्वदेशी जागरण मंच"
              }
            },
            {
              "id": "c",
              "text": {
                "en": "FICCI",
                "hi": "फिक्की"
              }
            },
            {
              "id": "d",
              "text": {
                "en": "Associated Chambers of Commerce",
                "hi": "एसोचैम"
              }
            }
          ],
          "correct_option_id": "b",
          "explanation": {
            "en": "Swadeshi Jagaran Manch urged the Prime Minister to deny operating permissions for SpaceX’s Starlink, emphasizing domestic infrastructure.",
            "hi": "स्वदेशी जागरण मंच ने प्रधानमंत्री से आग्रह किया कि घरेलू बुनियादी ढांचे पर जोर देते हुए स्पेसएक्स के स्टारलिंक को परिचालन अनुमति न दी जाए।"
          }
        },
        {
          "source_id": "5",
          "evidence": "According to CCB sources, the agency’s cybercrime wing had earlier questioned Rakesh Shetty in connection with the case",
          "prompt": {
            "en": "Who is the Kannada news channel head who secured interim-anticipatory bail in connection with a Karnataka 'sting operation' case?",
            "hi": "कर्नाटक 'स्टिंग ऑपरेशन' मामले के सिलसिले में अंतरिम अग्रिम जमानत हासिल करने वाले कन्नड़ समाचार चैनल के प्रमुख कौन हैं?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "V Harish",
                "hi": "वी हरीश"
              }
            },
            {
              "id": "b",
              "text": {
                "en": "Roop Kumar Yadav",
                "hi": "रूप कुमार यादव"
              }
            },
            {
              "id": "c",
              "text": {
                "en": "Rakesh Shetty",
                "hi": "राकेश शेट्टी"
              }
            },
            {
              "id": "d",
              "text": {
                "en": "Kashim Chowdhury",
                "hi": "काशिम चौधरी"
              }
            }
          ],
          "correct_option_id": "c",
          "explanation": {
            "en": "Kannada news channel head Rakesh Shetty secured interim-anticipatory bail after being questioned by the cybercrime wing.",
            "hi": "साइबर क्राइम विंग द्वारा पूछताछ के बाद कन्नड़ समाचार चैनल के प्रमुख राकेश शेट्टी ने अंतरिम अग्रिम जमानत हासिल की।"
          }
        },
        {
          "source_id": "6",
          "evidence": "The blast occurred in a house where firecrackers were being made; rescue operations under way",
          "prompt": {
            "en": "At least four people died in a blast in a house located in which district of Bihar?",
            "hi": "बिहार के किस जिले में एक घर में हुए धमाके में कम से कम चार लोगों की मौत हो गई?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "Siwan district",
                "hi": "सिवान जिला"
              }
            },
            {
              "id": "b",
              "text": {
                "en": "Patna district",
                "hi": "पटना जिला"
              }
            },
            {
              "id": "c",
              "text": {
                "en": "Muzaffarpur district",
                "hi": "मुजफ्फरपुर जिला"
              }
            },
            {
              "id": "d",
              "text": {
                "en": "Bhagalpur district",
                "hi": "भागलपुर जिला"
              }
            }
          ],
          "correct_option_id": "a",
          "explanation": {
            "en": "At least four individuals lost their lives in a firecracker-making house explosion in Bihar's Siwan district.",
            "hi": "बिहार के सीवान जिले में पटाखा बनाने वाले एक घर में हुए विस्फोट में कम से कम चार लोगों की जान चली गई।"
          }
        },
        {
          "source_id": "15",
          "evidence": "Every cetacean in India is protected under Schedule I of the Wildlife (Protection) Act 1972",
          "prompt": {
            "en": "Under which schedule of the Wildlife (Protection) Act 1972 are all cetaceans protected in India?",
            "hi": "वन्यजीव (संरक्षण) अधिनियम 1972 की किस अनुसूची के तहत भारत में सभी सेटेशियन (व्हेل आदि) संरक्षित हैं?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "Schedule IV",
                "hi": "अनुसूची IV"
              }
            },
            {
              "id": "b",
              "text": {
                "en": "Schedule III",
                "hi": "अनुसूची III"
              }
            },
            {
              "id": "c",
              "text": {
                "en": "Schedule II",
                "hi": "अनुसूची II"
              }
            },
            {
              "id": "d",
              "text": {
                "en": "Schedule I",
                "hi": "अनुसूची I"
              }
            }
          ],
          "correct_option_id": "d",
          "explanation": {
            "en": "Every cetacean in India enjoys protection under Schedule I of the Wildlife (Protection) Act 1972.",
            "hi": "भारत में प्रत्येक सेटेशियन वन्यजीव (संरक्षण) अधिनियम 1972 की अनुसूची I के तहत संरक्षित है।"
          }
        },
        {
          "source_id": "18",
          "evidence": "US Secretary of State Marco Rubio pushed a business and energy agenda over diplomacy on his second trip to India this year.",
          "prompt": {
            "en": "Who is the US Secretary of State who visited India on his second trip this year to push a business and energy agenda?",
            "hi": "इस वर्ष अपनी दूसरी यात्रा पर भारत आने वाले और व्यापार एवं ऊर्जा एजेंडे को आगे बढ़ाने वाले अमेरिकी विदेश मंत्री कौन हैं?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "Marco Rubio",
                "hi": "मार्को रुबियो"
              }
            },
            {
              "id": "b",
              "text": {
                "en": "Antony Blinken",
                "hi": "पिट एंटनी ब्लिंकन"
              }
            },
            {
              "id": "c",
              "text": {
                "en": "Lloyd Austin",
                "hi": "लॉयड ऑस्टिन"
              }
            },
            {
              "id": "d",
              "text": {
                "en": "Jake Sullivan",
                "hi": "जेक सुलिवन"
              }
            }
          ],
          "correct_option_id": "a",
          "explanation": {
            "en": "US Secretary of State Marco Rubio visited India to focus on business and energy.",
            "hi": "अमेरिकी विदेश मंत्री मार्को रुबियो ने व्यापार और ऊर्जा पर ध्यान केंद्रित करने के लिए भारत का दौरा किया।"
          }
        },
        {
          "source_id": "21",
          "evidence": "V Harish, who ran the hugely popular Instagram account \"Finance with Harish\", was found dead on Tuesday.",
          "prompt": {
            "en": "The popular Instagram account \"Finance with Harish\" was run by whom?",
            "hi": "लोकप्रिय इंस्टाग्राम अकाउंट \"फाइनेंस विद हरीश\" किसके द्वारा चलाया जाता था?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "Rakesh Shetty",
                "hi": "राकेश शेट्टी"
              }
            },
            {
              "id": "b",
              "text": {
                "en": "V Harish",
                "hi": "वी हरीश"
              }
            },
            {
              "id": "c",
              "text": {
                "en": "Kashim Chowdhury",
                "hi": "काशिम चौधरी"
              }
            },
            {
              "id": "d",
              "text": {
                "en": "Roop Kumar Yadav",
                "hi": "रूप कुमार यादव"
              }
            }
          ],
          "correct_option_id": "b",
          "explanation": {
            "en": "V Harish ran the popular Instagram account \"Finance with Harish\".",
            "hi": "वी हरीश लोकप्रिय इंस्टाग्राम अकाउंट \"फाइनेंस विद हरीश\" चलाते थे।"
          }
        },
        {
          "source_id": "24",
          "evidence": "Kashim Chowdhury denied being dishonest when not telling employers he had other jobs.",
          "prompt": {
            "en": "Who was charged with fraud after juggling five jobs without informing his employers?",
            "hi": "अपने नियोक्ताओं को बताए बिना पांच नौकरियां करने के बाद धोखाधड़ी का आरोपी किसे बनाया गया था?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "Rakesh Shetty",
                "hi": "राकेश शेट्टी"
              }
            },
            {
              "id": "b",
              "text": {
                "en": "V Harish",
                "hi": "वी हरीश"
              }
            },
            {
              "id": "c",
              "text": {
                "en": "Kashim Chowdhury",
                "hi": "काशिम चौधरी"
              }
            },
            {
              "id": "d",
              "text": {
                "en": "Roop Kumar Yadav",
                "hi": "रूप कुमार यादव"
              }
            }
          ],
          "correct_option_id": "c",
          "explanation": {
            "en": "Civil servant Kashim Chowdhury was charged with fraud for holding multiple jobs.",
            "hi": "सिविल सेवक काशिम चौधरी पर कई नौकरियां रखने के लिए धोखाधड़ी का आरोप लगाया गया था।"
          }
        },
        {
          "source_id": "33",
          "evidence": "The Welsh government says it is consulting on an \"undergrounding-first approach\" to electricity lines.",
          "prompt": {
            "en": "What does the Welsh government plan to ban as part of its newly launched consultation?",
            "hi": "वेल्श सरकार अपनी नई शुरू की गई परामर्श प्रक्रिया के हिस्से के रूप में किस पर प्रतिबंध लगाने की योजना बना रही है?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "Steel pylons",
                "hi": "स्टील के खंभे (पायलन)"
              }
            },
            {
              "id": "b",
              "text": {
                "en": "Diesel vehicles",
                "hi": "डीजल वाहन"
              }
            },
            {
              "id": "c",
              "text": {
                "en": "Plastic bags",
                "hi": "प्लास्टिक बैग"
              }
            },
            {
              "id": "d",
              "text": {
                "en": "Coal-fired generation",
                "hi": "कोयला आधारित उत्पादन"
              }
            }
          ],
          "correct_option_id": "a",
          "explanation": {
            "en": "The Welsh government launched a consultation on banning steel pylons by preferring an undergrounding-first approach.",
            "hi": "वेल्श सरकार ने भूमिगत दृष्टिकोण को प्राथमिकता देते हुए स्टील पाइल पर प्रतिबंध लगाने पर परामर्श शुरू किया है।"
          }
        },
        {
          "source_id": "36",
          "evidence": "Deadly shooting near Paris investigated as 'crime of terrorism', minister says",
          "prompt": {
            "en": "A deadly shooting near which European capital is being investigated as a 'crime of terrorism'?",
            "hi": "किस यूरोपीय राजधानी के पास हुई एक घातक गोलीबारी की जांच 'आतंकवाद के अपराध' के रूप में की जा रही है?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "London",
                "hi": "लंदन"
              }
            },
            {
              "id": "b",
              "text": {
                "en": "Berlin",
                "hi": "बर्लिन"
              }
            },
            {
              "id": "c",
              "text": {
                "en": "Paris",
                "hi": "पेरिस"
              }
            },
            {
              "id": "d",
              "text": {
                "en": "Madrid",
                "hi": "मैड्रिड"
              }
            }
          ],
          "correct_option_id": "c",
          "explanation": {
            "en": "A deadly shooting near Paris is being investigated as an act of terrorism.",
            "hi": "पेरिस के पास हुई घातक गोलीबारी की जांच आतंकवाद के कृत्य के रूप में की जा रही है।"
          }
        },
        {
          "source_id": "37",
          "evidence": "Another 28 people are injured in the southern Karak governorate, and a manhunt is now under way.",
          "prompt": {
            "en": "In which southern governorate did gunmen shoot dead six people at a church funeral?",
            "hi": "किस दक्षिणी गवर्नरट में बंदूकधारियों ने चर्च के अंतिम संस्कार में छह लोगों की गोली मारकर हत्या कर दी?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "Karak governorate",
                "hi": "करक गवर्नरट"
              }
            },
            {
              "id": "b",
              "text": {
                "en": "Amman governorate",
                "hi": "अम्मान गवर्नरट"
              }
            },
            {
              "id": "c",
              "text": {
                "en": "Zarqa governorate",
                "hi": "जरका गवर्नरट"
              }
            },
            {
              "id": "d",
              "text": {
                "en": "Irbid governorate",
                "hi": "इरबिड गवर्नरट"
              }
            }
          ],
          "correct_option_id": "a",
          "explanation": {
            "en": "Six people were shot dead at a church funeral in Jordan's southern Karak governorate.",
            "hi": "जॉर्डन के दक्षिणी करक गवर्नरट में एक चर्च के अंतिम संस्कार में छह लोगों की गोली मारकर हत्या कर दी गई।"
          }
        }
      ]
    },
    {
      "title": "Set 2: Economy, Business & Finance",
      "questions": [
        {
          "source_id": "7",
          "evidence": "Net FDI at $3.3 billion in September 2026, positive for third consecutive month",
          "prompt": {
            "en": "What was the net Foreign Direct Investment (FDI) figure recorded in September 2026?",
            "hi": "सितंबर 2026 में दर्ज शुद्ध प्रत्यक्ष विदेशी निवेश (FDI) का आंकड़ा कितना था?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "$1.2 billion",
                "hi": "$1.2 बिलियन"
              }
            },
            {
              "id": "b",
              "text": {
                "en": "$3.3 billion",
                "hi": "$3.3 बिलियन"
              }
            },
            {
              "id": "c",
              "text": {
                "en": "$5.0 billion",
                "hi": "$5.0 बिलियन"
              }
            },
            {
              "id": "d",
              "text": {
                "en": "$7.1 billion",
                "hi": "$7.1 बिलियन"
