          }
        },
        {
          "source_id": "8",
          "evidence": "Meta's ⁠move followed ⁠complaints by publishers and digital advertisers to European Union and the ​U.K. antitrust ‌authorities about its new commercial terms",
          "prompt": {
            "en": "Meta decided to delay new commercial terms following complaints to antitrust authorities of which regions?",
            "hi": "किस क्षेत्र के एंटीट्रस्ट प्राधिकरणों से शिकायत मिलने के बाद मेटा ने नई व्यावसायिक शर्तों में देरी करने का फैसला किया?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "European Union and the U.K.",
                "hi": "यूरोपीय संघ और यू.के."
              }
            },
            {
              "id": "b",
              "text": {
                "en": "United States and Canada",
                "hi": "संयुक्त राज्य अमेरिका और कनाडा"
              }
            },
            {
              "id": "c",
              "text": {
                "en": "Japan and South Korea",
                "hi": "जापान और दक्षिण कोरिया"
              }
            },
            {
              "id": "d",
              "text": {
                "en": "Australia and New Zealand",
                "hi": "ऑस्ट्रेलिया और न्यूजीलैंड"
              }
            }
          ],
          "correct_option_id": "a",
          "explanation": {
            "en": "Meta delayed terms after publishers complained to European Union and U.K. antitrust authorities.",
            "hi": "प्रकाशकों द्वारा यूरोपीय संघ और यू.के. के एंटीट्रस्ट प्राधिकरणों से शिकायत करने के बाद मेटा ने शर्तों में देरी की।"
          }
        },
        {
          "source_id": "9",
          "evidence": "Inflation in rural areas was found to be higher than in urban areas; headline CPI inflation edged up over the months",
          "prompt": {
            "en": "According to the RBI Bulletin, where was inflation found to be higher?",
            "hi": "आरबीआई बुलेटिन के अनुसार, कहाँ पर मुद्रास्फीति अधिक पाई गई?"
          },
          "options": [
